/**
 * Recover a server stuck in ERROR after a failed reinstall clone (its VM was
 * destroyed but the re-clone failed). Flips ONLY an ERROR server back to STOPPED
 * so the tested reinstall flow in the portal can rebuild it. Does nothing to a
 * server in any other state.
 *
 *   node scripts/recover-errored-server.mjs <hostname|serverId>
 *
 * After this, grant the missing Proxmox privilege (SDN.Use) and re-run the
 * reinstall from the portal — the clone will succeed and the VM is rebuilt.
 */
import { db } from "/opt/nxeon/lib/db.ts";

const arg = process.argv[2];
if (!arg) {
  console.error("Usage: node scripts/recover-errored-server.mjs <hostname|serverId>");
  process.exit(1);
}

const server = await db.server.findFirst({
  where: { OR: [{ id: arg }, { hostname: arg }] },
  select: { id: true, hostname: true, status: true, vmid: true },
});
if (!server) {
  console.error(`No server matching "${arg}".`);
  process.exit(1);
}
console.log(`Found ${server.hostname} (vmid ${server.vmid}) — status ${server.status}`);

if (server.status !== "ERROR") {
  console.log(`Not in ERROR (it's ${server.status}). Nothing changed — recovery only applies to an ERROR server.`);
  process.exit(0);
}

await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });
console.log(`✓ ${server.hostname} set to STOPPED.`);
console.log("  Next: in the portal, open this server → Resize/Reinstall → Erase & reinstall.");
console.log("  (Grant SDN.Use to the Proxmox role first, or the clone will 403 again.)");
process.exit(0);
