// One-shot SSH runner for the Soul Pilates staging deploy task.
// Reads a command from argv (or stdin with --stdin), runs it on server
// cmsc9l72y000ghl7iyd87u5ja, ASSERTS ip==51.79.226.200 before doing anything.
import { PrismaClient } from "@prisma/client";
import { Client } from "ssh2";
import { decryptSecret } from "/opt/nxeon/lib/crypto-box.ts";
import { readFileSync } from "node:fs";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const EXPECT_IP = "51.79.226.200";

const db = new PrismaClient();

async function main() {
  let cmd: string;
  if (process.argv[2] === "--stdin") {
    cmd = readFileSync(0, "utf8");
  } else {
    cmd = process.argv.slice(2).join(" ");
  }
  if (!cmd.trim()) {
    console.error("No command provided");
    process.exit(2);
  }

  const server = await db.server.findUnique({
    where: { id: SERVER_ID },
    select: { id: true, hostname: true, ipAddress: true, sshPort: true, rootPasswordEnc: true },
  });
  if (!server) throw new Error("Server not found");
  if (server.ipAddress !== EXPECT_IP) {
    throw new Error(`IP ASSERT FAILED: expected ${EXPECT_IP} got ${server.ipAddress}`);
  }
  const pw = decryptSecret(server.rootPasswordEnc);
  if (!pw) throw new Error("Could not decrypt root password");
  console.error(`[assert] ${server.hostname} ip=${server.ipAddress} OK`);

  const conn = new Client();
  const code: number = await new Promise((resolve, reject) => {
    conn.on("ready", () => {
      conn.exec(cmd, { pty: false }, (err, stream) => {
        if (err) return reject(err);
        stream
          .on("close", (c: number) => {
            conn.end();
            resolve(c ?? 0);
          })
          .on("data", (d: Buffer) => process.stdout.write(d))
          .stderr.on("data", (d: Buffer) => process.stderr.write(d));
      });
    });
    conn.on("error", reject);
    conn.connect({
      host: server.ipAddress!,
      port: server.sshPort ?? 22,
      username: "root",
      password: pw,
      readyTimeout: 30000,
    });
  });
  await db.$disconnect();
  process.exit(code);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

